### Description

The following error is thrown when redirecting to a url which includes encoded unicode characters.

```
"reqId":"req-1","err":{"type":"NodeError","message":"Invalid character in header content [\"location\"]","stack":"TypeError [ERR_INVALID_CHAR]: Invalid character in header content [\"location\"]
    at storeHeader (_http_outgoing.js:502:5)
```

This is reproducible with the following code

```js
// Require the framework and instantiate it
const fastify = require('fastify')({ logger: true })

// capture query parameters for redirection
global.prepParams = function (req){
	var query_parameters = '';
	for (const [key,value] of Object.entries(req.query)){
		if (query_parameters === '')
			query_parameters += '?';
		else
			query_parameters += '&';
		query_parameters += key + '=' + value;
	}
	return query_parameters;
};
// Declare a route
fastify.get('/1', async (req, reply) => {
	var query_parameters=prepParams(req);
	console.log('redirect url: ', '/2'+query_parameters);
	reply.redirect('/2'+query_parameters);
});
fastify.get('/2', async (req, reply) => {
  return { hello: 'world' }
});

// Run the server!
const start = async () => {
  try {
    await fastify.listen(3004)
  } catch (err) {
    fastify.log.error(err)
    process.exit(1)
  }
}
start()
```

A request to `'http://localhost:3004/1?key=ab'` succeeds, but a request to `http://localhost:3004/1?key=a%e2%80%99b` fails

### Steps to Reproduce

With the code above running, send request to `http://localhost:3004/1?key=a%e2%80%99b`

### Expected Behavior

_No response_

